"""Iterative deepener — multi-pass research with surprise + variance detection."""

import json
from typing import Callable, Optional

from ..hunger.claim_parser import ParsedClaim

_POSITIVE_SIGNALS = {"high", "growth", "strong", "rising", "increasing", "profitable", "success", "expand"}
_NEGATIVE_SIGNALS = {"low", "decline", "weak", "fail", "falling", "loss", "shrink", "collapse", "drop"}

_SPECIFICITY_MODIFIERS = [
    " statistics data",
    " actual numbers verified",
    " real case study",
]

_DIM_WEIGHTS: dict[str, float] = {
    "failure_rates": 2.5,
    "failure_patterns": 2.5,
    "unit_economics": 2.0,
    "competitive_landscape": 2.0,
    "moat_patterns": 2.0,
    "timing_windows": 1.8,
    "regulatory_risks": 1.8,
    "capital_requirements": 1.5,
    "compounding_mechanisms": 1.5,
    "founder_experience": 1.5,
    "base_rates": 2.0,
}


class IterativeDeepener:
    """Multi-pass research deepener.

    Detects surprising contradictions + high variance dimensions and fires
    targeted follow-up queries via research_fn.  Zero LLM calls.
    """

    def __init__(
        self,
        research_fn: Callable[[str], str],
        max_rounds: int = 2,
        max_deep_queries: int = 6,
    ):
        self.research_fn = research_fn
        self.max_rounds = max_rounds
        self.max_deep_queries = max_deep_queries

    # ── Public API ─────────────────────────────────────────────────────────────

    def deepen(
        self, dimension_scores: dict, facts: list[ParsedClaim]
    ) -> list[ParsedClaim]:
        """Run iterative deepening passes. Returns only NEW facts."""
        new_facts: list[ParsedClaim] = []
        queries_fired = 0

        for _round in range(self.max_rounds):
            if queries_fired >= self.max_deep_queries:
                break

            targets = self.detect_surprises(facts + new_facts)
            variance_dims = self.detect_high_variance(dimension_scores, facts + new_facts)

            # Merge + deduplicate targets
            target_dims: list[tuple[str, str, int]] = list(targets)
            existing_target_dims = {t[0] for t in targets}
            for d in variance_dims:
                if d not in existing_target_dims:
                    target_dims.append((d, "high_variance", 1))

            if not target_dims:
                break

            # Sort by priority desc
            target_dims.sort(key=lambda x: x[2], reverse=True)

            round_new: list[ParsedClaim] = []
            for dim, _reason, _prio in target_dims:
                if queries_fired >= self.max_deep_queries:
                    break
                deep_queries = self.generate_deep_queries(dim)
                for q in deep_queries:
                    if queries_fired >= self.max_deep_queries:
                        break
                    try:
                        raw = self.research_fn(q)
                        parsed = self._parse_result(raw, dim)
                        if parsed:
                            round_new.append(parsed)
                    except Exception:
                        pass
                    queries_fired += 1

            new_facts.extend(round_new)
            if not round_new:
                break

        return new_facts

    # ── Detection ─────────────────────────────────────────────────────────────

    def detect_surprises(
        self, facts: list[ParsedClaim]
    ) -> list[tuple[str, str, int]]:
        """Return list of (dimension, reason, priority) tuples."""
        surprises: list[tuple[str, str, int]] = []
        seen_dims: set[str] = set()

        # Group facts by dimension
        by_dim: dict[str, list[ParsedClaim]] = {}
        for f in facts:
            by_dim.setdefault(f.dimension, []).append(f)

        for dim, dim_facts in by_dim.items():
            if dim in seen_dims:
                continue

            # Contradiction detection — opposing sentiment in same dimension
            positives = [
                f for f in dim_facts
                if any(s in f.fact.lower() for s in _POSITIVE_SIGNALS)
            ]
            negatives = [
                f for f in dim_facts
                if any(s in f.fact.lower() for s in _NEGATIVE_SIGNALS)
            ]
            if positives and negatives:
                surprises.append((dim, "contradiction", 3))
                seen_dims.add(dim)
                continue

            # Low confidence on high-weight dimensions
            dim_weight = _DIM_WEIGHTS.get(dim, 1.0)
            if dim_weight >= 2.0:
                low_conf = [f for f in dim_facts if f.confidence < 0.4]
                if low_conf:
                    surprises.append((dim, "low_confidence_high_weight", 2))
                    seen_dims.add(dim)

        return surprises

    def detect_high_variance(
        self, dimension_scores: dict, facts: list[ParsedClaim]
    ) -> list[str]:
        """Return dimension names with mixed zone tags or uncertain scores."""
        high_var: list[str] = []

        # Facts grouped by dimension
        by_dim: dict[str, list[ParsedClaim]] = {}
        for f in facts:
            by_dim.setdefault(f.dimension, []).append(f)

        # Dims with both K and ? zone facts
        for dim, dim_facts in by_dim.items():
            zones = {f.zone_tag for f in dim_facts}
            if "K" in zones and "?" in zones:
                if dim not in high_var:
                    high_var.append(dim)

        # Dims with uncertain score (0.3-0.6) from dimension_scores dict
        for dim, score_info in dimension_scores.items():
            if isinstance(score_info, dict):
                score = score_info.get("score", 1.0)
            elif hasattr(score_info, "score"):
                score = score_info.score
            else:
                continue
            if 0.3 <= score <= 0.6 and dim not in high_var:
                high_var.append(dim)

        return high_var

    # ── Query Generation ───────────────────────────────────────────────────────

    def generate_deep_queries(
        self, dimension: str, original_queries: list[str] | None = None
    ) -> list[str]:
        """Generate up to 3 targeted follow-up queries for a dimension. LLM-free."""
        base = dimension.replace("_", " ")
        queries: list[str] = []

        # Variant 1: specificity modifier
        queries.append(f"{base}{_SPECIFICITY_MODIFIERS[0]}")

        # Variant 2: forum / operator layer
        queries.append(f"{base} forum actual experience reddit")

        # Variant 3: negation / failure lens
        queries.append(f"why {base} fails problems real cases")

        return queries[:3]

    # ── Internal ───────────────────────────────────────────────────────────────

    def _parse_result(self, raw: str, dimension: str) -> Optional[ParsedClaim]:
        """Parse research_fn output into ParsedClaim. Returns None on failure."""
        if not raw:
            return None
        try:
            data = json.loads(raw)
        except (json.JSONDecodeError, TypeError):
            return None

        fact = data.get("fact", "")
        if not fact or len(fact.strip()) < 5:
            return None

        conf = float(data.get("confidence", 0.5))
        zone = "K" if conf >= 0.75 else "T" if conf >= 0.5 else "?"

        value = data.get("value")
        try:
            value = float(value) if value is not None else None
        except (TypeError, ValueError):
            value = None

        return ParsedClaim(
            fact=fact[:300],
            value=value,
            dimension=dimension,
            source_url=data.get("source"),
            source_date=data.get("date"),
            confidence=conf,
            zone_tag=zone,
        )

"""Ladder bridge — non-Google source escalation when SEO saturation detected."""

import json
import subprocess
from pathlib import Path
from typing import Optional

from ..hunger.claim_parser import ParsedClaim

_DEFAULT_LADDER_PATH = (
    Path(__file__).resolve().parents[4]
    / "data"
    / "knowledge-sources"
    / "ladder-runner.py"
)

_SEO_PATTERNS = (
    "top ",
    "best ",
    "how to ",
    "/blog/",
    "aff=",
    "ref=",
    "utm_",
    " for beginners",
    " ultimate guide",
    " complete guide",
)

_VN_KEYWORDS = (
    "vietnam", " vn ", "dak lak", "tay nguyen", "mmo", "kiem tien",
    "kiếm tiền", "việt nam", "dắk lắk",
)
_SAAS_KEYWORDS = ("saas", "bootstrap", "micro-saas", "indie hacker", "mrr", "arr")
_VC_KEYWORDS = ("venture capital", "vc fund", "investment fund", "angel invest", "due diligence")


class LadderBridge:
    """Escalates research to non-Google sources when SEO saturation detected.

    Gracefully degrades if ladder-runner.py is unavailable.
    """

    def __init__(
        self,
        ladder_runner_path: Optional[str] = None,
        route_key: Optional[str] = None,
    ):
        if ladder_runner_path:
            self.ladder_path = Path(ladder_runner_path)
        else:
            self.ladder_path = _DEFAULT_LADDER_PATH

        self._available = self.ladder_path.exists()
        self.default_route = route_key

    # ── Public API ─────────────────────────────────────────────────────────────

    def should_escalate(self, search_results: list[str]) -> bool:
        """Return True if >= 60% of result snippets match SEO-pollution patterns."""
        if not search_results:
            return False
        polluted = sum(
            1 for r in search_results if self._is_seo_polluted(r)
        )
        return (polluted / len(search_results)) >= 0.6

    def detect_route(self, query: str) -> Optional[str]:
        """Classify query into a research ladder route key."""
        q = query.lower()
        if any(kw in q for kw in _VN_KEYWORDS):
            if any(w in q for w in ("mmo", "kiem tien", "kiếm tiền", "grey", "gray")):
                return "vn_greyhat_mmo"
            return "vn_legitimate_business"
        if any(kw in q for kw in _SAAS_KEYWORDS):
            return "western_bootstrap_saas"
        if any(kw in q for kw in _VC_KEYWORDS):
            return "founder_due_diligence"
        return None

    def run_ladder(self, topic: str, route_key: str) -> list[ParsedClaim]:
        """Invoke ladder-runner.py subprocess. Returns parsed facts or empty list."""
        if not self._available:
            return []
        try:
            proc = subprocess.run(
                [
                    "python",
                    str(self.ladder_path),
                    "--topic", topic,
                    "--route", route_key,
                ],
                capture_output=True,
                text=True,
                timeout=60,
            )
            if proc.returncode != 0:
                return []
            return self._parse_ladder_output(proc.stdout, route_key)
        except (subprocess.TimeoutExpired, FileNotFoundError, OSError):
            return []
        except Exception:
            return []

    # ── Internal ───────────────────────────────────────────────────────────────

    def _is_seo_polluted(self, snippet: str) -> bool:
        s = snippet.lower()
        return any(pat in s for pat in _SEO_PATTERNS)

    def _parse_ladder_output(self, raw: str, dimension: str) -> list[ParsedClaim]:
        """Parse JSON array or newline-delimited JSON from ladder-runner output."""
        if not raw.strip():
            return []

        facts: list[ParsedClaim] = []

        # Try JSON array first
        try:
            data = json.loads(raw)
            if isinstance(data, list):
                for item in data:
                    claim = self._item_to_claim(item, dimension)
                    if claim:
                        facts.append(claim)
                return facts
        except (json.JSONDecodeError, TypeError):
            pass

        # Try newline-delimited JSON
        for line in raw.splitlines():
            line = line.strip()
            if not line:
                continue
            try:
                item = json.loads(line)
                claim = self._item_to_claim(item, dimension)
                if claim:
                    facts.append(claim)
            except (json.JSONDecodeError, TypeError):
                continue

        return facts

    def _item_to_claim(self, item: dict, dimension: str) -> Optional[ParsedClaim]:
        if not isinstance(item, dict):
            return None
        fact = item.get("fact", item.get("text", item.get("content", "")))
        if not fact or len(str(fact).strip()) < 5:
            return None
        conf = float(item.get("confidence", 0.45))
        zone = "K" if conf >= 0.75 else "T" if conf >= 0.5 else "?"
        value = item.get("value")
        try:
            value = float(value) if value is not None else None
        except (TypeError, ValueError):
            value = None
        return ParsedClaim(
            fact=str(fact)[:300],
            value=value,
            dimension=dimension,
            source_url=item.get("source", item.get("url")),
            source_date=item.get("date"),
            confidence=conf,
            zone_tag=zone,
        )

